from collections import Counter

def transform(grid):
    sep = next(i for i, row in enumerate(grid) if len(set(row)) == 1 and row[0] not in (0,))
    top, bottom = grid[:sep], grid[sep + 1:]
    top_values = {v for row in top for v in row}
    bottom_values = {v for row in bottom for v in row}
    if 0 in top_values or 0 in bottom_values:
        top_fg = top_values - {0}
        bottom_fg = bottom_values - {0}
        marked = lambda a, b: a in top_fg and b in bottom_fg
    else:
        shared = top_values & bottom_values
        marked = lambda a, b: a in shared and b == a
    return [[3 if marked(a, b) else 2 for a, b in zip(r1, r2)] for r1, r2 in zip(top, bottom)]
